<style>
    .fi-header-heading,.fi-breadcrumbs{display:none!important}
    .fi-header{margin-bottom:8px!important;min-height:0!important}

    .orion-wh-inner,.orion-wh-inner *{box-sizing:border-box;font-family:'Cairo',sans-serif}
    .orion-wh-inner{--wi-panel:#0c1728;--wi-border:#21324d;--wi-border-soft:#17263c;--wi-text:#eef3fb;--wi-muted:#71839e;--wi-purple:#8b5cf6;--wi-green:#34d399;--wi-red:#fb7185;--wi-amber:#fbbf24;direction:rtl;color:var(--wi-text);width:100%;padding-bottom:24px}

    .wi-hero{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:116px;padding:17px 19px;margin-bottom:13px;border:1px solid var(--wi-border);border-radius:15px;background:radial-gradient(circle at 8% 10%,rgba(139,92,246,.16),transparent 28%),linear-gradient(145deg,#0e192b,#0a1423);box-shadow:0 18px 45px rgba(0,0,0,.12)}
    .wi-hero-main{display:flex;align-items:center;gap:13px;min-width:0}.wi-icon{width:48px;height:48px;border-radius:13px;flex:none;display:grid;place-items:center;color:#c3b2ff;border:1px solid rgba(139,92,246,.38);background:linear-gradient(145deg,rgba(124,58,237,.28),rgba(76,29,149,.12));box-shadow:0 10px 25px rgba(76,29,149,.16)}.wi-icon svg{width:22px;height:22px}
    .wi-eyebrow{color:#8e7be8;font-size:8px;font-weight:950;letter-spacing:1.3px;margin-bottom:4px}.wi-title{color:#f5f7fb;font-size:18px;font-weight:950;line-height:1.25}.wi-sub{color:var(--wi-muted);font-size:9px;font-weight:650;margin-top:5px}
    .wi-chips{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}.wi-chip{display:inline-flex;align-items:center;gap:6px;min-height:30px;padding:0 10px;border:1px solid #263a58;border-radius:9px;background:#0c1829;color:#9aabc0;font-size:8px;font-weight:900;white-space:nowrap}.wi-chip strong{color:#e4eaf3;font-size:9px;direction:ltr}.wi-chip.green{border-color:rgba(52,211,153,.23);background:rgba(52,211,153,.055);color:#6eddb8}.wi-chip.amber{border-color:rgba(251,191,36,.23);background:rgba(251,191,36,.055);color:#f4ca58}.wi-chip.gray{color:#8290a6}.wi-dot{width:6px;height:6px;border-radius:50%;background:currentColor;box-shadow:0 0 9px currentColor}

