    .wi-content .fi-section + .fi-section{margin-top:11px!important}.wi-content .fi-section-header{border-bottom:1px solid var(--wi-border-soft)!important;background:rgba(255,255,255,.012)!important}.wi-content .fi-section-header-heading{color:#e8edf5!important;font-weight:950!important}.wi-content .fi-section-header-description{color:#657792!important;font-size:10px!important}
    .wi-content .fi-input-wrp,.wi-content .fi-fo-file-upload-input-ctn{border-color:#263a59!important;background:#0d192b!important;box-shadow:none!important}.wi-content .fi-input,.wi-content textarea{color:#e1e8f2!important}.wi-content .fi-fo-field-wrp-label{color:#9aa9bd!important;font-weight:800!important}.wi-content .fi-fo-field-wrp-helper-text{color:#596c87!important}
    .wi-content .fi-in-entry{min-height:62px}.wi-content .fi-in-entry-label{color:#667a95!important;font-size:9px!important;font-weight:850!important}.wi-content .fi-in-text{color:#e4eaf3!important;font-weight:750!important}

