    .wi-content .fi-ta-ctn,.wi-content .fi-ta{border-color:#21324d!important;border-radius:14px!important;background:#0b1524!important;box-shadow:none!important;overflow:hidden!important}.wi-content .fi-ta-header{background:rgba(255,255,255,.012)!important;border-bottom:1px solid #17263c!important}.wi-content .fi-ta-table thead{background:#0e192a!important}.wi-content .fi-ta-table thead th{color:#657892!important;font-size:9px!important;font-weight:900!important}.wi-content .fi-ta-row{border-bottom:1px solid #15243a!important}.wi-content .fi-ta-row:hover{background:rgba(139,92,246,.035)!important}.wi-content .fi-ta-cell{color:#c9d3e1!important;font-size:9px!important}.wi-content .fi-ta-pagination{border-top:1px solid #18283f!important}

